// File: Lockness/contract/ShopOptimized.sol


pragma solidity ^0.8.20;






contract Shop is Ownable, ReentrancyGuard, EIP712 {
    using SafeERC20 for IERC20;

    // ===============================
    // Errors
    // ===============================
    error InvalidSignature();
    error OrderExpired();
    error InvalidBuyer();
    error InvalidChainId();
    error InvalidContract();
    error OrderAlreadyProcessed();
    error SignerNotSet();

    // ===============================
    // Order
    // ===============================
    struct Order {
        bytes32 orderId;
        address buyer;
        uint256 itemId;
        uint256 quantity;
        uint256 totalAmount;
        address paymentToken;
        uint256 expiresAt;
        uint256 chainId;
        address contractAddress;
    }

    bytes32 private constant ORDER_TYPEHASH =
        keccak256(
            "Order(bytes32 orderId,address buyer,uint256 itemId,uint256 quantity,uint256 totalAmount,address paymentToken,uint256 expiresAt,uint256 chainId,address contractAddress)"
        );

    // ===============================
    // Storage
    // ===============================
    address public serverSigner;
    mapping(bytes32 => bool) public processedOrders;

    // ===============================
    // Events
    // ===============================
    event Purchased(
        bytes32 indexed orderId,
        address indexed buyer,
        uint256 indexed itemId,
        uint256 quantity,
        uint256 totalAmount,
        address paymentToken
    );

    event SignerUpdated(address signer);

    // ===============================
    // Constructor
    // ===============================
    constructor(address owner_)
        Ownable(owner_)
        EIP712("Shop", "1")
    {}

    // ===============================
    // Admin
    // ===============================
    function setServerSigner(address signer) external onlyOwner {
        serverSigner = signer;
        emit SignerUpdated(signer);
    }

    // ===============================
    // Buy
    // ===============================
    function buy(
        Order calldata order,
        bytes calldata signature
    ) external nonReentrant {
        if (serverSigner == address(0)) revert SignerNotSet();
        if (order.buyer != msg.sender) revert InvalidBuyer();
        if (order.expiresAt < block.timestamp) revert OrderExpired();
        if (order.chainId != block.chainid) revert InvalidChainId();
        if (order.contractAddress != address(this)) revert InvalidContract();
        if (processedOrders[order.orderId]) revert OrderAlreadyProcessed();

        // Verify BE signature
        bytes32 digest = _hashTypedDataV4(
            keccak256(
                abi.encode(
                    ORDER_TYPEHASH,
                    order.orderId,
                    order.buyer,
                    order.itemId,
                    order.quantity,
                    order.totalAmount,
                    order.paymentToken,
                    order.expiresAt,
                    order.chainId,
                    order.contractAddress
                )
            )
        );

        address recovered = ECDSA.recover(digest, signature);
        if (recovered != serverSigner) revert InvalidSignature();

        // Mark processed
        processedOrders[order.orderId] = true;

        // Transfer token
        IERC20(order.paymentToken).safeTransferFrom(
            msg.sender,
            address(this),
            order.totalAmount
        );

        emit Purchased(
            order.orderId,
            msg.sender,
            order.itemId,
            order.quantity,
            order.totalAmount,
            order.paymentToken
        );
    }

    // ===============================
    // Withdraw
    // ===============================
    function withdraw(
        address token,
        address to,
        uint256 amount
    ) external onlyOwner {
        IERC20(token).safeTransfer(to, amount);
    }
}

